function shell(content){return `<div class="admin-layout"><aside class="admin-sidebar"><a class="admin-brand" href="../index.html"><img src="../assets/goregisterlogo.png" alt="" /><span><strong>GO REGISTER</strong><small>Administração</small></span></a><span class="admin-nav-label">GERENCIAMENTO</span><nav class="admin-nav" aria-label="Navegação administrativa"><button class="${section==="companies"?"active":""}" data-section="companies">Empresas</button><button class="${section==="subscriptions"?"active":""}" data-section="subscriptions">Assinaturas</button><button class="${section==="administrators"?"active":""}" data-section="administrators">Administradores</button><button class="${section==="updates"?"active":""}" data-section="updates">Atualização do APK</button></nav><div class="admin-sidebar-footer"><button class="btn secondary" id="logout">Sair</button></div></aside><main class="admin-shell"><header class="admin-header"><div><h1>Administração</h1><p class="muted">Gerencie empresas, assinaturas, administradores e versões da plataforma.</p></div></header>${content}</main></div>${message?`<aside class="admin-toast" role="status" aria-live="polite"><span>${esc(message)}</span><button type="button" data-dismiss-message aria-label="Fechar notificação">×</button></aside>`:""}`}

const adminFilters = {
  companies: { search: "", status: "ALL" },
  subscriptions: { search: "", status: "ALL" },
  administrators: { search: "", status: "ALL" },
};
function adminFilteredRecords(records, tab) {
  const filter = adminFilters[tab];
  const query = normalized(filter.search);
  const digits = identifierDigits(query);
  return records.filter(record => {
    const subscription = tab === "subscriptions" ? subscriptionState(record) : null;
    const fields = tab === "administrators"
      ? [record.name, record.email]
      : [record.name, record.identifier, companyTaxIdentifier(record), subscription?.subscription.planName];
    const matchesText = !query || normalized(fields.join(" ")).includes(query)
      || (tab !== "administrators" && digits && /^[\d\s./-]+$/.test(query)
        && [record.identifier, companyTaxIdentifier(record)].some(value => identifierDigits(value).includes(digits)));
    const matchesStatus = filter.status === "ALL"
      || (filter.status === "ACTIVE" && record.isActive !== false)
      || (filter.status === "INACTIVE" && record.isActive === false)
      || (filter.status === "OVERDUE" && subscription?.overdue)
      || (filter.status === "BLOCKED" && subscription?.blocked)
      || (filter.status === "ALLOWED" && subscription && !subscription.blocked);
    return matchesText && matchesStatus;
  });
}
function adminSearchToolbar(tab, count, total) {
  const filter = adminFilters[tab];
  const placeholder = tab === "administrators" ? "Nome ou e-mail" : tab === "subscriptions" ? "Empresa, plano, identificador ou CPF/CNPJ" : "Nome, identificador ou CPF/CNPJ";
  const options = tab === "subscriptions"
    ? [["ALL", "Todas"], ["OVERDUE", "Vencidas"], ["BLOCKED", "Acesso bloqueado"], ["ALLOWED", "Acesso liberado"]]
    : [["ALL", "Todos"], ["ACTIVE", "Ativos"], ["INACTIVE", "Inativos"]];
  return `<div class="admin-search-toolbar"><label class="field"><span>Buscar</span><span class="input-wrap"><input id="adminSearch" type="search" value="${esc(filter.search)}" placeholder="${placeholder}" autocomplete="off" /></span></label><label class="field"><span>Status</span><span class="input-wrap"><select id="adminStatusFilter">${options.map(([value, label]) => `<option value="${value}" ${value === filter.status ? "selected" : ""}>${label}</option>`).join("")}</select></span></label><button type="button" class="btn secondary" id="adminClearFilters" ${!filter.search && filter.status === "ALL" ? "disabled" : ""}>Limpar filtros</button><small class="muted admin-result-count" role="status">${count} de ${total} registro(s)</small></div>`;
}
function bindAdminSearch() {
  document.querySelector("#adminSearch")?.addEventListener("input", event => {
    const cursor = event.target.selectionStart;
    adminFilters[section].search = event.target.value;
    render();
    const input = document.querySelector("#adminSearch");
    input.focus();
    input.setSelectionRange(cursor, cursor);
  });
  document.querySelector("#adminStatusFilter")?.addEventListener("change", event => {
    adminFilters[section].status = event.target.value;
    render();
    document.querySelector("#adminStatusFilter")?.focus();
  });
  document.querySelector("#adminClearFilters")?.addEventListener("click", () => {
    adminFilters[section] = { search: "", status: "ALL" };
    render();
    document.querySelector("#adminSearch")?.focus();
  });
}

function companyView(){const filtered=adminFilteredRecords(companies,"companies");const rows=filtered.map(company=>{const count=users.filter(user=>user.empresa_id===company.id).length,access=receivablesAccess(company.receivablesEntitlement,company.receivablesConfigured);return `<tr><td><strong>${esc(company.name)}</strong></td><td>${esc(company.identifier)}</td><td>${esc(companyTaxIdentifier(company)||"-")}</td><td><span class="status-dot ${company.isActive===false?"":"active"}"></span>${company.isActive===false?"Inativa":"Ativa"}</td><td><span class="addon-badge ${access.allowed?"enabled":"disabled"}">${esc(access.label)}</span><small>${esc(access.reason)}</small></td><td>${count}</td><td>${date(company.createdAt)}</td><td class="admin-actions"><button class="btn secondary compact" data-edit-company="${company.id}">Editar</button><button class="btn secondary compact" data-toggle-company="${company.id}">${company.isActive===false?"Ativar":"Desativar"}</button><button class="btn danger compact" data-delete-company="${company.id}">Excluir</button></td></tr>`}).join("");return `<div class="section-heading"><div><h2>Empresas</h2><p class="muted">Cadastre empresas e controle individualmente os módulos contratados.</p></div><button class="btn" id="newCompany">Nova empresa</button></div>${adminSearchToolbar("companies",filtered.length,companies.length)}<section class="panel admin-table"><table><thead><tr><th>Empresa</th><th>Identificador de acesso</th><th>CPF/CNPJ</th><th>Status</th><th>Contas a Receber</th><th>Usuários</th><th>Criação</th><th>Ações</th></tr></thead><tbody>${rows||'<tr><td colspan="8" class="admin-empty muted">Nenhuma empresa encontrada.</td></tr>'}</tbody></table></section>${companyModalOpen?companyModal():""}`}
function subscriptionView(){const filtered=adminFilteredRecords(companies,"subscriptions");const active=companies.filter(company=>company.isActive!==false).length,blocked=companies.length-active,overdue=companies.filter(company=>subscriptionState(company).overdue).length,monthly=companies.reduce((total,company)=>{const item=subscriptionState(company).subscription;if(company.isActive===false||item.status!=="ACTIVE")return total;if(item.billingCycle==="MONTHLY")return total+Number(item.priceCents||0);if(item.billingCycle==="YEARLY")return total+Math.round(Number(item.priceCents||0)/12);return total},0),rows=filtered.map(company=>{const state=subscriptionState(company),subscription=state.subscription,moduleAccess=receivablesAccess(company.receivablesEntitlement,company.receivablesConfigured),statusClass=state.blocked||["SUSPENDED","CANCELLED"].includes(subscription.status)?"disabled":"enabled";return `<tr><td><strong>${esc(company.name)}</strong><small>${esc(subscription.planName)}</small></td><td><span class="addon-badge ${statusClass}">${esc(state.label)}</span><small>${state.blocked?"Site e aplicativo bloqueados":"Acesso geral liberado"}</small></td><td><strong>${esc(new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(Number(subscription.priceCents||0)/100))}</strong><small>${esc({MONTHLY:"Mensal",YEARLY:"Anual",ONE_TIME:"Único"}[subscription.billingCycle]||subscription.billingCycle)}</small></td><td>${date(subscription.nextDueAt)}${state.overdue?'<small class="subscription-overdue">Vencimento ultrapassado</small>':""}</td><td>${date(subscription.graceUntil)}</td><td><span class="addon-badge ${moduleAccess.allowed?"enabled":"disabled"}">${esc(moduleAccess.label)}</span></td><td class="admin-actions"><button class="btn secondary compact" data-edit-subscription="${company.id}">Gerenciar</button><button class="btn ${state.blocked?"secondary":"danger"} compact" data-toggle-subscription-access="${company.id}">${state.blocked?"Liberar acesso":"Bloquear acesso"}</button></td></tr>`}).join("");return `<div class="section-heading"><div><h2>Painel de assinaturas</h2><p class="muted">Acompanhe cobranças, vencimentos, módulos adicionais e o acesso de cada empresa.</p></div></div><section class="subscription-metrics"><article class="panel"><span>Empresas ativas</span><strong>${active}</strong></article><article class="panel"><span>Acessos bloqueados</span><strong>${blocked}</strong></article><article class="panel"><span>Assinaturas vencidas</span><strong>${overdue}</strong></article><article class="panel"><span>Receita mensal estimada</span><strong>${esc(new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(monthly/100))}</strong></article></section>${adminSearchToolbar("subscriptions",filtered.length,companies.length)}<section class="panel admin-table subscription-table"><table><thead><tr><th>Empresa/Plano</th><th>Situação e acesso</th><th>Valor</th><th>Próximo vencimento</th><th>Tolerância</th><th>Módulo adicional</th><th>Ações</th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="admin-empty muted">Nenhuma empresa encontrada.</td></tr>'}</tbody></table></section>${subscriptionModalOpen?subscriptionModal():""}`}
function subscriptionModal(){const company=editingCompany,state=subscriptionState(company),subscription=state.subscription;return `<div class="admin-modal-backdrop" data-close-modal><section class="admin-modal" role="dialog" aria-modal="true"><button class="admin-modal-close" type="button" data-close-modal aria-label="Fechar">×</button><form class="admin-form" id="subscriptionForm"><h2>Assinatura de ${esc(company.name)}</h2><p class="modal-context">O bloqueio de acesso impede novas sessões no site e no aplicativo.</p><label class="field"><span>Nome do plano</span><span class="input-wrap"><input name="subscriptionPlanName" maxlength="80" value="${esc(subscription.planName)}" required></span></label><label class="field"><span>Situação</span><span class="input-wrap"><select name="subscriptionStatus">${subscriptionStatuses.map(status=>`<option value="${status}" ${subscription.status===status?"selected":""}>${esc(subscriptionStatusLabel(status))}</option>`).join("")}</select></span></label><label class="field"><span>Valor contratado</span><span class="input-wrap"><input name="subscriptionPrice" type="number" min="0" max="9999999.99" step="0.01" value="${Number(subscription.priceCents||0)/100}"></span></label><label class="field"><span>Ciclo</span><span class="input-wrap"><select name="subscriptionBillingCycle"><option value="MONTHLY" ${subscription.billingCycle==="MONTHLY"?"selected":""}>Mensal</option><option value="YEARLY" ${subscription.billingCycle==="YEARLY"?"selected":""}>Anual</option><option value="ONE_TIME" ${subscription.billingCycle==="ONE_TIME"?"selected":""}>Pagamento único</option></select></span></label><label class="field"><span>Próximo vencimento</span><span class="input-wrap"><input name="subscriptionNextDueAt" type="date" value="${esc(millisDateInput(subscription.nextDueAt))}"></span></label><label class="field"><span>Tolerância até</span><span class="input-wrap"><input name="subscriptionGraceUntil" type="date" value="${esc(millisDateInput(subscription.graceUntil))}"></span></label><label class="field"><span>Avisar com antecedência</span><span class="input-wrap"><input name="subscriptionNoticeDays" type="number" min="0" max="60" value="${Number(company.mainSubscriptionNoticeDays??7)}" required></span><small class="field-help">Quantidade de dias antes do vencimento em que o alerta aparecerá.</small></label><label class="field"><span>Acesso da empresa</span><span class="input-wrap"><select name="subscriptionAccess"><option value="true" ${company.isActive===false?"":"selected"}>Liberado</option><option value="false" ${company.isActive===false?"selected":""}>Bloqueado</option></select></span></label><label class="field"><span>Contas a Receber</span><span class="input-wrap"><input value="${esc(receivablesAccess(company.receivablesEntitlement,company.receivablesConfigured).label)}" disabled></span><small class="field-help">O módulo adicional continua sendo configurado no cadastro da empresa.</small></label><label class="field"><span>Observações administrativas</span><span class="input-wrap textarea-wrap"><textarea name="subscriptionNotes" maxlength="1000" rows="4">${esc(subscription.notes)}</textarea></span></label><div class="form-actions"><button class="btn" type="submit">Salvar assinatura</button><button class="btn secondary" type="button" data-close-modal>Cancelar</button></div></form></section></div>`}
function androidUpdateView(){const config=androidUpdateConfig,active=config.enabled===true,published=config.publishedAt?date(config.publishedAt):"-",forceLatest=androidUpdateExists&&config.minimumVersionCode===config.latestVersionCode;return `<div class="section-heading"><div><h2>Atualização automática do APK</h2></div></div>${androidUpdateLoadError?`<p class="error">${esc(androidUpdateLoadError)}</p>`:""}<section class="panel update-panel"><form class="admin-form" id="androidUpdateForm"><div class="company-form-grid"><label class="field"><span>Nome da nova versão</span><span class="input-wrap"><input name="latestVersionName" maxlength="50" placeholder="Ex.: 1.8" value="${esc(config.latestVersionName)}" required></span></label><label class="field"><span>Código da nova versão</span><span class="input-wrap"><input name="latestVersionCode" type="number" min="1" max="2147483647" step="1" value="${esc(config.latestVersionCode)}" required></span></label><label class="field"><span>Código mínimo aceito</span><span class="input-wrap"><input name="minimumVersionCode" type="number" min="1" max="2147483647" step="1" value="${esc(config.minimumVersionCode)}" required></span></label><label class="update-check"><input name="forceLatest" type="checkbox" ${forceLatest?"checked":""}><span><strong>Tornar obrigatória para todas as versões anteriores</strong><small>Use somente depois de confirmar a instalação em uma empresa de teste.</small></span></label><label class="field field-wide"><span>URL oficial do APK</span><span class="input-wrap"><input name="apkUrl" type="url" maxlength="2048" placeholder="https://github.com/ShinaS2-WEB/go_Register_apk/releases/download/.../GO_REGISTER.apk" value="${esc(config.apkUrl)}" required></span></label><label class="field field-wide"><span>SHA-256 do APK</span><span class="input-wrap"><input name="sha256" maxlength="64" minlength="64" spellcheck="false" placeholder="64 caracteres do hash" value="${esc(config.sha256)}"></span></label><label class="field field-wide"><span>Notas da atualização</span><span class="input-wrap textarea-wrap"><textarea name="releaseNotes" maxlength="5000" rows="8" placeholder="Descreva as novidades para os clientes.">${esc(config.releaseNotes)}</textarea></span></label></div><label class="update-check update-enable"><input name="enabled" type="checkbox" ${active?"checked":""}><span><strong>Exibir esta atualização no aplicativo</strong><small>Desmarque para salvar a configuração sem avisar os clientes.</small></span></label><p class="field-help">Última publicação: ${esc(published)}. O painel não envia o APK nem guarda tokens do GitHub.</p><div class="form-actions"><button class="btn" type="submit">Salvar configuração</button></div></form></section>`}
function companyModal(){
  const profile=editingCompany?.profile||{},receiptSettings=editingCompany?.receiptSettings||{},entitlement=editingCompany?.receivablesEntitlement||defaultReceivablesEntitlement(),billing=editingCompany?.receivablesBilling||defaultReceivablesBilling(),receivablesConfigured=editingCompany?.receivablesConfigured===true,receivablesPreview=receivablesAccess(entitlement,receivablesConfigured),companyUsers=editingCompany?users.filter(user=>user.empresa_id===editingCompany.id):[];
  const taxIdentifier=editingCompany?companyTaxIdentifier(editingCompany):"";
  const userRows=companyUsers.map(user=>`<tr><td><strong>${esc(user.username||"-")}</strong><small>${esc(user.email||"-")}</small></td><td>${esc(roleLabel(user.role))}</td><td><span class="status-dot ${user.isActive===false?"":"active"}"></span>${user.isActive===false?"Inativo":"Ativo"}</td><td class="admin-actions"><button class="btn secondary compact" type="button" data-edit-company-user="${user.uid}">Editar</button><button class="btn danger compact" type="button" data-delete-company-user="${user.uid}">Excluir</button></td></tr>`).join("");
  return `<div class="admin-modal-backdrop" data-close-modal><section class="admin-modal admin-modal-wide company-modal" role="dialog" aria-modal="true" aria-labelledby="companyModalTitle"><button class="admin-modal-close" type="button" data-close-modal aria-label="Fechar">×</button><form class="admin-form" id="companyForm"><div class="company-modal-heading"><div><h2 id="companyModalTitle">${editingCompany?"Editar empresa":"Nova empresa"}</h2><p class="muted">Os dados profissionais são administrados exclusivamente por este painel.</p></div></div>
  <fieldset class="company-form-section"><legend>Identificação da empresa</legend><div class="company-form-grid">
    <label class="field"><span>Nome fantasia *</span><span class="input-wrap"><input name="name" maxlength="160" value="${esc(editingCompany?.name)}" required autofocus></span></label>
    <label class="field"><span>Razão social</span><span class="input-wrap"><input name="legalName" maxlength="180" value="${esc(profile.legalName)}"></span></label>
    <label class="field"><span>Filial ou unidade</span><span class="input-wrap"><input name="unitName" maxlength="120" value="${esc(profile.unitName)}" placeholder="Ex.: Matriz, Unidade Centro"></span></label>
    <label class="field"><span>Identificador de acesso *</span><span class="input-wrap"><input name="identifier" maxlength="80" value="${esc(editingCompany?.identifier)}" placeholder="Ex.: salgaderia-sousa" autocomplete="off" required></span><small class="field-help">Código usado para entrar na empresa.</small></label>
    <label class="field"><span>CNPJ ou CPF *</span><span class="input-wrap"><input name="taxIdentifier" maxlength="18" inputmode="numeric" value="${esc(taxIdentifier)}" placeholder="00.000.000/0000-00" required></span></label>
    <label class="field"><span>Data de abertura</span><span class="input-wrap"><input name="openingDate" type="date" value="${esc(profile.openingDate)}"></span></label>
    <label class="field"><span>Inscrição estadual</span><span class="input-wrap"><input name="stateRegistration" maxlength="40" value="${esc(profile.stateRegistration)}"></span></label>
    <label class="field"><span>Inscrição municipal</span><span class="input-wrap"><input name="municipalRegistration" maxlength="40" value="${esc(profile.municipalRegistration)}"></span></label>
    <label class="field"><span>CNAE principal</span><span class="input-wrap"><input name="cnae" maxlength="14" inputmode="numeric" placeholder="0000-0/00" value="${esc(profile.cnae)}"></span></label>
    <label class="field"><span>Regime tributário</span><span class="input-wrap"><input name="taxRegime" maxlength="80" list="taxRegimeOptions" value="${esc(profile.taxRegime)}" placeholder="Selecione ou digite"></span></label>
    <datalist id="taxRegimeOptions"><option value="MEI"><option value="Simples Nacional"><option value="Lucro Presumido"><option value="Lucro Real"><option value="Imune/Isenta"></datalist>
    <label class="field"><span>Status *</span><span class="input-wrap"><select name="isActive"><option value="true" ${editingCompany?.isActive===false?"":"selected"}>Ativa</option><option value="false" ${editingCompany?.isActive===false?"selected":""}>Inativa</option></select></span></label>
  </div></fieldset>
  <fieldset class="company-form-section"><legend>Contato e localização</legend><div class="company-form-grid">
    <label class="field field-wide"><span>Endereço completo *</span><span class="input-wrap"><input name="address" maxlength="240" value="${esc(editingCompany?.address)}" placeholder="Rua, número, complemento, bairro, cidade, UF e CEP" required></span></label>
    <label class="field"><span>Telefone *</span><span class="input-wrap"><input name="phone" type="tel" maxlength="20" inputmode="tel" value="${esc(editingCompany?.phone)}" placeholder="(00) 00000-0000" required></span></label>
    <label class="field"><span>E-mail comercial</span><span class="input-wrap"><input name="email" type="email" maxlength="160" autocomplete="email" value="${esc(profile.email)}"></span></label>
    <label class="field field-wide"><span>Site</span><span class="input-wrap"><input name="website" type="text" maxlength="240" inputmode="url" placeholder="empresa.com.br" value="${esc(profile.website)}"></span></label>
    <label class="field field-wide"><span>URL do logotipo</span><span class="input-wrap"><input name="logoUrl" type="url" maxlength="500" inputmode="url" placeholder="https://empresa.com.br/logo.png" value="${esc(profile.logoUrl)}"></span><small class="field-help">Use um endereço público e seguro iniciado por https://.</small></label>
    <label class="field field-wide"><span>Redes sociais</span><span class="input-wrap"><input name="socialMedia" maxlength="240" placeholder="Ex.: @empresa ou https://instagram.com/empresa" value="${esc(receiptSettings.socialMedia)}"></span></label>
  </div></fieldset>
  <fieldset class="company-form-section"><legend>Responsável e recebimentos</legend><div class="company-form-grid">
    <label class="field"><span>Nome do responsável</span><span class="input-wrap"><input name="responsibleName" maxlength="160" value="${esc(profile.responsibleName)}"></span></label>
    <label class="field"><span>Cargo ou função</span><span class="input-wrap"><input name="responsibleRole" maxlength="100" value="${esc(profile.responsibleRole)}"></span></label>
    <label class="field field-wide"><span>Chave Pix comercial</span><span class="input-wrap"><input name="pixKey" maxlength="180" value="${esc(profile.pixKey)}" autocomplete="off"></span></label>
  </div></fieldset>
  <fieldset class="company-form-section"><legend>Recibos e atendimento</legend><div class="company-form-grid">
    <label class="field field-wide"><span>Mensagem personalizada do recibo</span><span class="input-wrap textarea-wrap"><textarea name="receiptMessage" maxlength="500" rows="3" placeholder="Ex.: Agradecemos pela preferência!">${esc(receiptSettings.receiptMessage)}</textarea></span><small class="field-help">Texto opcional para o rodapé dos recibos.</small></label>
    <label class="field field-wide"><span>Política de troca, devolução ou garantia</span><span class="input-wrap textarea-wrap"><textarea name="exchangePolicy" maxlength="1200" rows="4" placeholder="Informe prazos e condições aplicáveis.">${esc(receiptSettings.exchangePolicy)}</textarea></span></label>
    <label class="field field-wide"><span>Observações institucionais</span><span class="input-wrap textarea-wrap"><textarea name="institutionalNotes" maxlength="1000" rows="3" placeholder="Informações adicionais sobre a empresa.">${esc(profile.institutionalNotes)}</textarea></span></label>
  </div></fieldset>
  <fieldset class="company-form-section receivables-addon"><legend>Adicional pago — Contas a Receber</legend><div class="addon-intro"><div><strong>Liberação individual por empresa</strong><p>Ative este módulo apenas para clientes que contrataram venda fiada e controle de dívidas.</p></div><span class="addon-badge ${receivablesPreview.allowed?"enabled":"disabled"}" id="receivablesAccessBadge">${esc(receivablesPreview.label)}</span></div><div class="company-form-grid">
    <label class="field"><span>Módulo contratado *</span><span class="input-wrap"><select name="receivablesEnabled"><option value="false" ${entitlement.enabled===true?"":"selected"}>Desativado</option><option value="true" ${entitlement.enabled===true?"selected":""}>Ativado</option></select></span></label>
    <label class="field"><span>Situação *</span><span class="input-wrap"><select name="receivablesStatus"><option value="TRIAL" ${entitlement.status==="TRIAL"?"selected":""}>Período de teste</option><option value="ACTIVE" ${entitlement.status==="ACTIVE"?"selected":""}>Ativo</option><option value="PAST_DUE" ${entitlement.status==="PAST_DUE"?"selected":""}>Pagamento atrasado</option><option value="SUSPENDED" ${entitlement.status==="SUSPENDED"?"selected":""}>Suspenso</option></select></span></label>
    <label class="field"><span>Validade do acesso</span><span class="input-wrap"><input name="receivablesValidUntil" type="date" value="${esc(millisDateInput(entitlement.validUntil))}"></span><small class="field-help">Em branco significa acesso sem data final. A validade inclui todo o dia escolhido.</small></label>
    <label class="field"><span>Valor contratado</span><span class="input-wrap"><input name="receivablesPrice" type="number" min="0" max="9999999.99" step="0.01" inputmode="decimal" value="${(Number(billing.priceCents)||0)/100}"></span></label>
    <label class="field"><span>Ciclo da cobrança</span><span class="input-wrap"><select name="receivablesBillingCycle"><option value="MONTHLY" ${billing.billingCycle==="MONTHLY"?"selected":""}>Mensal</option><option value="YEARLY" ${billing.billingCycle==="YEARLY"?"selected":""}>Anual</option><option value="ONE_TIME" ${billing.billingCycle==="ONE_TIME"?"selected":""}>Pagamento único</option></select></span></label>
    <label class="field"><span>Próximo vencimento</span><span class="input-wrap"><input name="receivablesNextDueAt" type="date" value="${esc(millisDateInput(billing.nextDueAt))}"></span></label>
    <label class="field field-wide"><span>Observações administrativas</span><span class="input-wrap textarea-wrap"><textarea name="receivablesNotes" maxlength="1000" rows="3" placeholder="Ex.: valor promocional, forma combinada de pagamento ou observações do contrato.">${esc(billing.notes)}</textarea></span></label>
  </div><p class="field-help">Ao suspender ou vencer, a empresa não cria novas contas, mas continua consultando o histórico e recebendo dívidas existentes. Uma empresa que nunca teve o adicional ativado não terá documentos do módulo criados.</p></fieldset>
  ${editingCompany?"":`<fieldset class="company-form-section"><legend>Acesso inicial</legend><div class="company-form-grid"><label class="field"><span>Usuário do administrador *</span><span class="input-wrap"><input name="adminUsername" minlength="3" maxlength="80" required></span></label><label class="field"><span>Senha inicial *</span><span class="input-wrap"><input name="adminPassword" type="password" minlength="6" maxlength="128" autocomplete="new-password" required></span></label></div></fieldset>`}
  <div class="form-actions company-form-actions"><button class="btn" type="submit">Salvar empresa</button><button class="btn secondary" type="button" data-close-modal>Cancelar</button></div></form>
  ${editingCompany?`<div class="company-users"><div class="company-users-heading"><div><h3>Usuários da empresa</h3><p class="muted">Somente usuários vinculados a ${esc(editingCompany.name)}.</p></div><button class="btn" type="button" id="newCompanyUser">Novo usuário</button></div><div class="admin-table"><table><thead><tr><th>Usuário</th><th>Perfil</th><th>Status</th><th>Ações</th></tr></thead><tbody>${userRows||'<tr><td colspan="4" class="admin-empty muted">Nenhum usuário cadastrado nesta empresa.</td></tr>'}</tbody></table></div></div><div class="company-admin-tools"><h3>Controle administrativo</h3><p class="muted">Ações privilegiadas que não exigem as senhas atuais da empresa.</p><div class="form-actions"><button class="btn secondary" type="button" id="resetCancellationPassword">Redefinir senha de cancelamento</button><button class="btn danger" type="button" id="clearCompanyData">Limpar todos os dados da empresa</button></div><p class="field-help">A limpeza preserva a empresa, seus usuários e os dados profissionais, mas apaga produtos, vendas, caixa, históricos e configurações operacionais.</p></div>`:""}</section></div>`
}
function administratorView(){const filtered=adminFilteredRecords(administrators,"administrators");const rows=filtered.map(administrator=>`<tr><td><strong>${esc(administrator.name||"Administrador")}</strong></td><td>${esc(administrator.email||"-")}</td><td><span class="status-dot ${administrator.isActive===false?"":"active"}"></span>${administrator.isActive===false?"Inativo":"Ativo"}</td><td>${date(administrator.createdAt)}</td><td class="admin-actions"><button class="btn secondary compact" data-edit-administrator="${administrator.uid}">Editar</button><button class="btn danger compact" data-delete-administrator="${administrator.uid}">Excluir</button></td></tr>`).join("");return `<div class="section-heading"><div><h2>Administradores</h2><p class="muted">Gerencie somente as contas que acessam este site de administração.</p></div><button class="btn" id="newAdministrator">Novo administrador</button></div>${administratorLoadError?`<p class="error">${esc(administratorLoadError)}</p>`:""}${adminSearchToolbar("administrators",filtered.length,administrators.length)}<section class="panel admin-table"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Status</th><th>Criação</th><th>Ações</th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="admin-empty muted">Nenhum administrador encontrado.</td></tr>'}</tbody></table></section>${administratorModalOpen?administratorModal():""}`}
function administratorModal(){return `<div class="admin-modal-backdrop" data-close-modal><section class="admin-modal" role="dialog" aria-modal="true" aria-labelledby="administratorModalTitle"><button class="admin-modal-close" type="button" data-close-modal aria-label="Fechar">×</button><form class="admin-form" id="administratorForm"><h2 id="administratorModalTitle">${editingAdministrator?"Editar administrador":"Novo administrador"}</h2><label class="field"><span>Nome</span><span class="input-wrap"><input name="name" value="${esc(editingAdministrator?.name)}" required autofocus></span></label><label class="field"><span>E-mail</span><span class="input-wrap"><input name="email" type="email" value="${esc(editingAdministrator?.email)}" ${editingAdministrator?"disabled":"required"}></span></label>${editingAdministrator?'<p class="field-help">O e-mail de autenticação não pode ser alterado por este painel.</p>':'<label class="field"><span>Senha inicial</span><span class="input-wrap"><input name="password" type="password" minlength="6" required></span></label>'}<label class="field"><span>Status</span><span class="input-wrap"><select name="isActive"><option value="true" ${editingAdministrator?.isActive===false?"":"selected"}>Ativo</option><option value="false" ${editingAdministrator?.isActive===false?"selected":""}>Inativo</option></select></span></label><div class="form-actions"><button class="btn" type="submit">Salvar administrador</button><button class="btn secondary" type="button" data-close-modal>Cancelar</button></div></form></section></div>`}
function companyUsersView(){const rows=users.map(user=>`<tr><td><strong>${esc(user.username||"-")}</strong><small>${esc(user.email||"-")}</small></td><td>${esc(companyName(user.empresa_id))}</td><td>${esc(roleLabel(user.role))}</td><td><span class="status-dot ${user.isActive===false?"":"active"}"></span>${user.isActive===false?"Inativo":"Ativo"}</td><td>${date(user.createdAt)}</td><td class="admin-actions"><button class="btn secondary compact" data-edit-user="${user.uid}">Editar</button><button class="btn danger compact" data-delete-user="${user.uid}">Excluir</button></td></tr>`).join("");return `<div class="section-heading"><div><h2>Usuários das empresas</h2><p class="muted">Gerencie as contas utilizadas pelas empresas cadastradas.</p></div><button class="btn" id="newUser" ${companies.length?"":"disabled"}>Novo usuário</button></div><section class="panel admin-table"><table><thead><tr><th>Usuário</th><th>Empresa</th><th>Perfil</th><th>Status</th><th>Criação</th><th>Ações</th></tr></thead><tbody>${rows||'<tr><td colspan="6" class="admin-empty muted">Nenhum usuário de empresa cadastrado.</td></tr>'}</tbody></table></section>${userModalOpen?userModal():""}`}
function userModal(){const selectedCompany=editingCompany||companies.find(company=>company.id===editingUser?.empresa_id);return `<div class="admin-modal-backdrop user-modal-layer" data-close-user-modal><section class="admin-modal" role="dialog" aria-modal="true" aria-labelledby="userModalTitle"><button class="admin-modal-close" type="button" data-close-user-modal aria-label="Fechar">×</button><form class="admin-form" id="userForm"><h2 id="userModalTitle">${editingUser?"Editar usuário":"Novo usuário"}</h2><p class="modal-context">Empresa: <strong>${esc(selectedCompany?.name)}</strong></p><input type="hidden" name="empresa_id" value="${esc(selectedCompany?.id)}"><label class="field"><span>Nome de usuário</span><span class="input-wrap"><input name="username" minlength="3" value="${esc(editingUser?.username)}" required autofocus></span></label>${editingUser?'<label class="field"><span>Nova senha</span><span class="input-wrap"><input name="password" type="password" minlength="6" maxlength="128" autocomplete="new-password" placeholder="Deixe em branco para manter a atual"></span></label><p class="field-help">Ao preencher, a senha atual será substituída imediatamente.</p>':'<label class="field"><span>Senha inicial</span><span class="input-wrap"><input name="password" type="password" minlength="6" maxlength="128" required></span></label>'}<label class="field"><span>Perfil</span><span class="input-wrap"><select name="role"><option value="OPERATOR" ${editingUser?.role==="OPERATOR"?"selected":""}>Operador</option><option value="ADMIN" ${editingUser?.role==="ADMIN"?"selected":""}>Administrador</option><option value="MASTER_ADMIN" ${editingUser?.role==="MASTER_ADMIN"?"selected":""}>Administrador mestre</option></select></span></label><label class="field"><span>Status</span><span class="input-wrap"><select name="isActive"><option value="true" ${editingUser?.isActive===false?"":"selected"}>Ativo</option><option value="false" ${editingUser?.isActive===false?"selected":""}>Inativo</option></select></span></label><div class="form-actions"><button class="btn" type="submit">Salvar usuário</button><button class="btn secondary" type="button" data-close-user-modal>Cancelar</button></div></form></section></div>`}
function confirmationModal(){if(!confirming)return "";const label=confirming.type==="company"?confirming.item.name:(confirming.item.name||confirming.item.username||confirming.item.email);if(confirming.type==="company")return `<div class="admin-modal-backdrop"><section class="admin-modal" role="alertdialog" aria-modal="true"><form class="admin-form" id="confirmCompanyDeleteForm"><h2>Excluir empresa</h2><p>Você está prestes a excluir <strong>${esc(label)}</strong> e seus vínculos.</p><p class="muted">Confirme as credenciais do administrador do painel. Esta ação não poderá ser desfeita.</p><label class="field"><span>E-mail do administrador do painel</span><span class="input-wrap"><input name="platformAdminEmail" type="email" autocomplete="username" required autofocus></span></label><label class="field"><span>Senha do administrador do painel</span><span class="input-wrap"><input name="platformAdminPassword" type="password" autocomplete="current-password" required></span></label><label class="field"><span>Digite <strong>EXCLUIR</strong> para confirmar</span><span class="input-wrap"><input name="confirmation" autocomplete="off" required></span></label>${adminToolError?`<p class="error">${esc(adminToolError)}</p>`:""}<div class="form-actions"><button class="btn danger" type="submit">Autenticar e excluir</button><button class="btn secondary" type="button" data-cancel-delete>Cancelar</button></div></form></section></div>`;return `<div class="admin-modal-backdrop"><section class="admin-modal admin-confirm" role="alertdialog" aria-modal="true"><h2>Confirmar exclusão</h2><p>Deseja realmente excluir <strong>${esc(label)}</strong>?</p><p class="muted">Esta ação não poderá ser desfeita.</p><div class="form-actions"><button class="btn danger" id="confirmDelete">Excluir</button><button class="btn secondary" type="button" data-cancel-delete>Cancelar</button></div></section></div>`}
function adminToolModal(){if(!adminTool)return "";const company=adminTool.company;if(adminTool.type==="password")return `<div class="admin-modal-backdrop user-modal-layer" data-close-admin-tool><section class="admin-modal" role="dialog" aria-modal="true"><button class="admin-modal-close" type="button" data-close-admin-tool aria-label="Fechar">×</button><form class="admin-form" id="cancellationPasswordForm"><h2>Redefinir senha de cancelamento</h2><p class="modal-context">Empresa: <strong>${esc(company.name)}</strong></p><label class="field"><span>Nova senha</span><span class="input-wrap"><input name="password" type="password" minlength="6" maxlength="128" autocomplete="new-password" required autofocus></span></label><label class="field"><span>Confirmar nova senha</span><span class="input-wrap"><input name="confirmation" type="password" minlength="6" maxlength="128" autocomplete="new-password" required></span></label>${adminToolError?`<p class="error">${esc(adminToolError)}</p>`:""}<div class="form-actions"><button class="btn" type="submit">Redefinir senha</button><button class="btn secondary" type="button" data-close-admin-tool>Cancelar</button></div></form></section></div>`;return `<div class="admin-modal-backdrop user-modal-layer" data-close-admin-tool><section class="admin-modal" role="alertdialog" aria-modal="true"><button class="admin-modal-close" type="button" data-close-admin-tool aria-label="Fechar">×</button><form class="admin-form" id="clearCompanyDataForm"><h2>Autorizar limpeza dos dados</h2><p>Esta ação apagará produtos, vendas, caixa, movimentações, históricos, categorias, fornecedores e configurações de <strong>${esc(company.name)}</strong>.</p><p class="muted">A empresa e seus usuários serão preservados. Confirme as credenciais do administrador do painel.</p><label class="field"><span>E-mail do administrador do painel</span><span class="input-wrap"><input name="platformAdminEmail" type="email" autocomplete="username" required autofocus></span></label><label class="field"><span>Senha do administrador do painel</span><span class="input-wrap"><input name="platformAdminPassword" type="password" autocomplete="current-password" required></span></label><label class="field"><span>Digite <strong>LIMPAR</strong> para confirmar</span><span class="input-wrap"><input name="confirmation" autocomplete="off" required></span></label>${adminToolError?`<p class="error">${esc(adminToolError)}</p>`:""}<div class="form-actions"><button class="btn danger" type="submit">Autenticar e limpar dados</button><button class="btn secondary" type="button" data-close-admin-tool>Cancelar</button></div></form></section></div>`}
function bindReceivablesPreview(){const form=document.querySelector("#companyForm"),badge=document.querySelector("#receivablesAccessBadge");if(!form||!badge)return;const update=()=>{try{const configuration=receivablesConfigurationFromForm(Object.fromEntries(new FormData(form))),configured=shouldPersistReceivables(configuration,editingCompany?.receivablesConfigured===true),access=receivablesAccess(configuration.entitlement,configured);badge.textContent=access.label;badge.className=`addon-badge ${access.allowed?"enabled":"disabled"}`}catch{}};["receivablesEnabled","receivablesStatus","receivablesValidUntil","receivablesPrice","receivablesNextDueAt","receivablesNotes"].forEach(name=>form.elements.namedItem(name)?.addEventListener("input",update));form.elements.namedItem("receivablesBillingCycle")?.addEventListener("change",update)}
async function saveMainSubscription(company,formElement){const form=Object.fromEntries(new FormData(formElement)),subscription=mainSubscriptionFromForm(form),isActive=form.subscriptionAccess==="true";if(company.dataDeletionInProgress===true&&isActive)throw Error("Conclua a limpeza ou exclusão pendente antes de liberar esta empresa.");const batch=writeBatch(db);batch.set(doc(db,"companies",company.id,"billing","main_subscription"),subscription);batch.set(doc(db,"companies",company.id,"entitlements","main_subscription"),{status:subscription.status,nextDueAt:subscription.nextDueAt,graceUntil:subscription.graceUntil,noticeDays:subscription.noticeDays,updatedAt:subscription.updatedAt,updatedByUid:subscription.updatedByUid});batch.update(doc(db,"companies",company.id),{isActive,updatedAt:serverTimestamp()});await batch.commit()}
function render(){const view=section==="administrators"?administratorView():section==="updates"?androidUpdateView():section==="subscriptions"?subscriptionView():companyView();root.innerHTML=shell(view+(userModalOpen?userModal():"")+confirmationModal()+adminToolModal());document.querySelector("#companyForm [name=adminEmail]")?.closest("label")?.remove();document.querySelector("#logout").onclick=()=>signOut(auth);document.querySelectorAll("[data-section]").forEach(button=>button.onclick=()=>{section=button.dataset.section;editingCompany=null;editingAdministrator=null;editingUser=null;companyModalOpen=false;subscriptionModalOpen=false;administratorModalOpen=false;userModalOpen=false;confirming=null;adminTool=null;adminToolError="";message="";render()});bindModalEvents();bindAdminSearch();if(section==="companies"){bindCompanyEvents();bindReceivablesPreview()}else if(section==="subscriptions")bindSubscriptionEvents();else if(section==="administrators")bindAdministratorEvents();else bindAndroidUpdateEvents()}
function closeFormModal(){editingCompany=null;editingAdministrator=null;editingUser=null;companyModalOpen=false;subscriptionModalOpen=false;administratorModalOpen=false;userModalOpen=false;adminTool=null;adminToolError="";render()}
function bindModalEvents(){document.querySelector("[data-dismiss-message]")?.addEventListener("click",()=>{message="";render()});document.querySelectorAll("[data-close-modal]").forEach(element=>element.onclick=event=>{if(event.target===element||element.tagName==="BUTTON")closeFormModal()});document.querySelectorAll("[data-close-user-modal]").forEach(element=>element.onclick=event=>{if(event.target===element||element.tagName==="BUTTON"){editingUser=null;userModalOpen=false;companyModalOpen=true;render()}});document.querySelectorAll("[data-close-admin-tool]").forEach(element=>element.onclick=event=>{if(event.target===element||element.tagName==="BUTTON"){adminTool=null;adminToolError="";render()}});document.querySelector("[data-cancel-delete]")?.addEventListener("click",()=>{confirming=null;adminToolError="";render()});document.querySelector("#confirmDelete")?.addEventListener("click",async event=>{event.currentTarget.disabled=true;event.currentTarget.textContent="Excluindo...";try{const target=confirming;confirming=null;if(target.type==="user")await removeUser(target.item);else await removeAdministrator(target.item)}catch(error){confirming=null;message=error.message||"Falha ao excluir.";render()}});document.querySelector("#confirmCompanyDeleteForm")?.addEventListener("submit",async event=>{event.preventDefault();const form=new FormData(event.currentTarget),confirmation=String(form.get("confirmation")||"").trim().toUpperCase();if(confirmation!=="EXCLUIR"){adminToolError='Digite "EXCLUIR" para confirmar.';return render()}const button=event.currentTarget.querySelector("button[type=submit]"),company=confirming.item;button.disabled=true;button.textContent="Autenticando...";try{await verifyPlatformAdministrator(form.get("platformAdminEmail"),form.get("platformAdminPassword"));button.textContent="Excluindo...";confirming=null;adminToolError="";await removeCompany(company)}catch(error){if(!confirming)confirming={type:"company",item:company};adminToolError=error.message||"Falha ao autenticar e excluir a empresa.";render()}})}
function bindAdminTools(){document.querySelector("#resetCancellationPassword")?.addEventListener("click",()=>{adminTool={type:"password",company:editingCompany};adminToolError="";render()});document.querySelector("#clearCompanyData")?.addEventListener("click",()=>{adminTool={type:"clear",company:editingCompany};adminToolError="";render()});document.querySelector("#cancellationPasswordForm")?.addEventListener("submit",async event=>{event.preventDefault();const form=new FormData(event.currentTarget),password=String(form.get("password")||""),confirmation=String(form.get("confirmation")||"");if(password.length<6){adminToolError="A senha deve ter pelo menos 6 caracteres.";return render()}if(password!==confirmation){adminToolError="As senhas não conferem.";return render()}const button=event.currentTarget.querySelector("button[type=submit]");button.disabled=true;button.textContent="Redefinindo...";try{await resetCancellationPasswordDirect(adminTool.company.id,password);adminTool=null;adminToolError="";message="Senha de cancelamento redefinida com sucesso."}catch(error){adminToolError=error.message||"Falha ao redefinir a senha de cancelamento."}render()});document.querySelector("#clearCompanyDataForm")?.addEventListener("submit",async event=>{event.preventDefault();const form=new FormData(event.currentTarget),confirmation=String(form.get("confirmation")||"").trim().toUpperCase();if(confirmation!=="LIMPAR"){adminToolError='Digite "LIMPAR" para confirmar.';return render()}const button=event.currentTarget.querySelector("button[type=submit]"),company=adminTool.company;button.disabled=true;button.textContent="Autenticando...";try{await verifyPlatformAdministrator(form.get("platformAdminEmail"),form.get("platformAdminPassword"));button.textContent="Limpando dados...";const deletedDocuments=await clearCompanyDataDirect(company.id);adminTool=null;adminToolError="";message=`Dados de ${company.name} limpos com sucesso. ${deletedDocuments} registros apagados.`}catch(error){adminToolError=error.message||"Falha ao autenticar e limpar os dados da empresa."}render()})}
function bindCompanyEvents(){document.querySelector("#newCompany").onclick=()=>{editingCompany=null;companyModalOpen=true;render()};if(document.querySelector("#companyForm"))document.querySelector("#companyForm").onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector("button[type=submit]");button.disabled=true;button.textContent="Salvando...";try{await saveCompany(event.currentTarget);editingCompany=null;companyModalOpen=false;await load("Empresa salva com sucesso.")}catch(error){message=error.message||"Falha ao salvar empresa.";render()}};document.querySelectorAll("[data-edit-company]").forEach(button=>button.onclick=()=>{editingCompany=companies.find(item=>item.id===button.dataset.editCompany);companyModalOpen=true;render()});document.querySelectorAll("[data-delete-company]").forEach(button=>button.onclick=()=>{adminToolError="";confirming={type:"company",item:companies.find(item=>item.id===button.dataset.deleteCompany)};render()});document.querySelectorAll("[data-toggle-company]").forEach(button=>button.onclick=async()=>{const company=companies.find(item=>item.id===button.dataset.toggleCompany);if(company.dataDeletionInProgress===true){button.disabled=true;button.textContent="Desbloqueando...";try{await recoverCompanyDataDeletion(company);return await load("Empresa desbloqueada e acesso restaurado.")}catch(error){message=error.message||"Falha ao desbloquear a empresa.";return render()}}await updateDoc(doc(db,"companies",company.id),{isActive:company.isActive===false,updatedAt:serverTimestamp()});await load("Status da empresa atualizado.")});document.querySelector("#newCompanyUser")?.addEventListener("click",()=>{editingUser=null;userModalOpen=true;render()});document.querySelectorAll("[data-edit-company-user]").forEach(button=>button.onclick=()=>{editingUser=users.find(user=>user.uid===button.dataset.editCompanyUser);userModalOpen=true;render()});document.querySelectorAll("[data-delete-company-user]").forEach(button=>button.onclick=()=>{confirming={type:"user",item:users.find(user=>user.uid===button.dataset.deleteCompanyUser)};render()});bindAdminTools();bindUserForm()}
function bindSubscriptionEvents(){document.querySelectorAll("[data-edit-subscription]").forEach(button=>button.onclick=()=>{editingCompany=companies.find(company=>company.id===button.dataset.editSubscription);subscriptionModalOpen=true;render()});document.querySelectorAll("[data-toggle-subscription-access]").forEach(button=>button.onclick=async()=>{const company=companies.find(item=>item.id===button.dataset.toggleSubscriptionAccess);if(company.dataDeletionInProgress===true&&company.isActive===false){message="Conclua a limpeza ou exclusão pendente antes de liberar esta empresa.";return render()}await updateDoc(doc(db,"companies",company.id),{isActive:company.isActive===false,updatedAt:serverTimestamp()});await load(company.isActive===false?"Acesso da empresa liberado.":"Acesso da empresa bloqueado.")});document.querySelector("#subscriptionForm")?.addEventListener("submit",async event=>{event.preventDefault();const button=event.currentTarget.querySelector("button[type=submit]"),company=editingCompany;button.disabled=true;button.textContent="Salvando...";try{await saveMainSubscription(company,event.currentTarget);editingCompany=null;subscriptionModalOpen=false;await load("Assinatura atualizada com sucesso.")}catch(error){message=error.message||"Falha ao salvar a assinatura.";render()}})}
function bindAdministratorEvents(){document.querySelector("#newAdministrator").onclick=()=>{editingAdministrator=null;administratorModalOpen=true;render()};if(document.querySelector("#administratorForm"))document.querySelector("#administratorForm").onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector("button[type=submit]");button.disabled=true;button.textContent="Salvando...";try{await saveAdministrator(event.currentTarget);editingAdministrator=null;administratorModalOpen=false;await load("Administrador salvo com sucesso.")}catch(error){message=error.message||"Falha ao salvar administrador.";render()}};document.querySelectorAll("[data-edit-administrator]").forEach(button=>button.onclick=()=>{editingAdministrator=administrators.find(item=>item.uid===button.dataset.editAdministrator);administratorModalOpen=true;render()});document.querySelectorAll("[data-delete-administrator]").forEach(button=>button.onclick=()=>{const item=administrators.find(item=>item.uid===button.dataset.deleteAdministrator);if(item.uid===auth.currentUser?.uid){message="Você não pode excluir a conta administrativa que está usando.";return render()}confirming={type:"administrator",item};render()})}
function bindAndroidUpdateEvents(){const form=document.querySelector("#androidUpdateForm");if(!form)return;const force=form.elements.namedItem("forceLatest"),minimum=form.elements.namedItem("minimumVersionCode"),latest=form.elements.namedItem("latestVersionCode");const syncMinimum=()=>{minimum.disabled=force.checked;if(force.checked)minimum.value=latest.value};force.addEventListener("change",syncMinimum);latest.addEventListener("input",()=>{if(force.checked)minimum.value=latest.value});syncMinimum();form.addEventListener("submit",async event=>{event.preventDefault();const button=form.querySelector("button[type=submit]");button.disabled=true;button.textContent="Salvando...";try{const payload=normalizeAndroidUpdateConfig(Object.fromEntries(new FormData(form)),Date.now(),auth.currentUser?.uid||"");await setDoc(doc(db,...ANDROID_UPDATE_DOCUMENT_PATH),payload);androidUpdateConfig=payload;androidUpdateExists=true;androidUpdateLoadError="";message=payload.enabled?"Atualização publicada para o aplicativo.":"Configuração salva sem avisar os clientes."}catch(error){message=error.message||"Não foi possível salvar a atualização."}render()})}
function bindUserForm(){if(document.querySelector("#userForm"))document.querySelector("#userForm").onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector("button[type=submit]");button.disabled=true;button.textContent="Salvando...";try{await saveUser(event.currentTarget);editingUser=null;userModalOpen=false;companyModalOpen=true;await load("Usuário salvo com sucesso.")}catch(error){message=error.message||"Falha ao salvar usuário.";render()}}}
renderLogin();
onAuthStateChanged(auth,async user=>{if(!user)return renderLogin();try{const access=await getDoc(doc(db,"platform_admins",user.uid));if(!access.exists()||access.data().isActive===false){await signOut(auth);return renderLogin("Esta conta não possui autorização administrativa.")}await load()}catch(error){await signOut(auth).catch(()=>{});renderLogin(error.message||"Não foi possível validar a sessão administrativa.")}});
